									<script>
										function getTitleForTypeCSWD(type){
											var result = "";
											if (type == "poslan_spisak_datum"){
												result = "Prikupljanje dokumentacije i unos datuma poslanog spiska";
											} else if (type == "dokumentacija_kompletna_datum") {
												result = "Dokumentacija kompletna i unos datuma kada je stigla kompletna dokumentacija od kandidata";
											} else if (type == "na_prevodu_datum") {
												result = "Na prevodu i unos datuma kada je dokumentacija poslana na prevod";
											}else if (type == "prevod_zavrsen_datum") {
												result = "Prevod završen i unos datuma kada je prevod završen";
											}else if (type == "poslana_posta_datum") {
												result = "Poslana pošta i unos datuma kada je poslana pošta za kandidata";
											}else if (type == "zaprimljena_dokumentacija_datum") {
												result = "Zaprimljena dokumentacija sa unos datuma kada je dokumentacija stigla na ustanovu i fotografija potvrde";
											}else if (type == "stigla_taksa_dopuna_datum") {
												result = "Stigla taksa / dopuna i unos datuma kada je stigla taksa / dopuna";
											}else if (type == "placena_taksa_poslana_dopuna_datum") {
												result = "Placena taksa / poslana dopuna i unos datuma kada je placena taksa / poslana dopuna";
											}else if (type == "zavrsen_datum") {
												result = "Završen i unos datuma kada je stigla nostrifikovana diploma";
											}else {
												result = "Nepoznato";
											}

											return result;
										};

										$(".change_status_ND_with_date").click( function() {
											var addressValueWithDate = $(this).attr("data"); 
											var datumKolonaWithDate = $(this).attr("data-datum_kolona_cs"); 
											var modalTitleWithDate = getTitleForTypeCSWD(datumKolonaWithDate);

											if ( datumKolonaWithDate == "zaprimljena_dokumentacija_datum") {
												$('#file_show_hide_CSWD').show();
												$('#file_CSWD').prop('required',true);
											} else {
												$('#file_show_hide_CSWD').hide();
												$('#file_CSWD').prop('required',false);
											}

											/*console.log("Address: "+addressValueWithDate);
											console.log("Datum: "+datumKolonaWithDate);*/
											$('#form_change_status_ND_with_date').attr('action', addressValueWithDate);
											$("#datum_kolona_CSWD").val(datumKolonaWithDate);
											$("#modal_title_CSWD").text(modalTitleWithDate);
										});
									</script>
