																												<script>
																													function getTitleForType(type){
																														var result = "";
																														if (type == "poslan_spisak_datum"){
																															result = "Poslan spisak dokumentacije";
																														} else if (type == "dokumentacija_kompletna_datum") {
																															result = "Dokumentacija kompletirana";
																														} else if (type == "na_prevodu_datum") {
																															result = "Poslano na prevod";
																														}else if (type == "prevod_zavrsen_datum") {
																															result = "Prevod završen";
																														}else if (type == "poslana_posta_datum") {
																															result = "Poslana pošta";
																														}else if (type == "zaprimljena_dokumentacija_datum") {
																															result = "Zaprimljena dokumentacija";
																														}else if (type == "stigla_taksa_dopuna_datum") {
																															result = "Stigla taksa / dopuna";
																														}else if (type == "placena_taksa_poslana_dopuna_datum") {
																															result = "Placena taksa / poslana dopuna";
																														}else if (type == "zavrsen_datum") {
																															result = "Završen";
																														}else {
																															result = "Nepoznato";
																														}

																														return result;
																													};

																													function getValueForType(type){
																														var result = "";
																														if (type == "poslan_spisak_datum"){
																															result = "<?php echo ( ($poslan_spisak_datum != null) ? $poslan_spisak_datum : '' ); ?>";
																														} else if (type == "dokumentacija_kompletna_datum") {
																															result = "<?php echo ( ($dokumentacija_kompletna_datum != null) ? $dokumentacija_kompletna_datum : '' ); ?>";
