																															result = "<?php echo ( ($stigla_taksa_dopuna_datum != null) ? $stigla_taksa_dopuna_datum : '' ); ?>";
																														}else if (type == "placena_taksa_poslana_dopuna_datum") {
																															result = "<?php echo ( ($placena_taksa_poslana_dopuna_datum != null) ? $placena_taksa_poslana_dopuna_datum : '' ); ?>";
																														}else if (type == "zavrsen_datum") {
																															result = "<?php echo ( ($zavrsen_datum != null) ? $zavrsen_datum : '' ); ?>";
																														}else {
																															result = '';
																														}

																														return result;
																													};

																													function dodaj_datum_obrada_set(thisRow) {
																														var type_datum_obrada = $(thisRow).data("type_datum_obrada");
																														var datum_obrada_modal_title = getTitleForType(type_datum_obrada);
																														var datum_obrada_default_value = getValueForType(type_datum_obrada);
																														//console.log(type_datum_obrada);
																														$("#type_datum_obrada_field").val(type_datum_obrada);
																														$("#modal_title_dodaj_datum_obrada").text(datum_obrada_modal_title);
																														$("#datum_obrada_field").val(datum_obrada_default_value);
																													};

