																						<?php
																							$tipovi_dokumenta_ustanove_k_ispis = $db->prepare("
																																				SELECT 
																																				* 
																																				FROM 
																																				idk_nd_ustanove_tip_dokumenta
																																				WHERE 
																																				(
																																					idd_ustanove_nd = :idd_ustanove_nd 
																																					AND
																																					idd_skole_ustanove_nd is null
																																					AND
																																					idd_skole_smjer_ustanove_nd is null
																																				)
																																				OR
																																				(
																																					idd_ustanove_nd = :idd_ustanove_nd
																																					AND
																																					idd_skole_ustanove_nd
																																					IN
																																					(
																																						SELECT
																																						id_skole_ustanove_nd
																																						FROM
																																						idk_nd_ustanove_skola
																																						WHERE
																																						(
																																							idd_ustanove_nd = :idd_ustanove_nd
																																							AND
																																							skola_idd = :skola_idd
																																						)
																																					)
																																					AND 
																																					idd_skole_smjer_ustanove_nd is null
																																				)
																																				OR
																																				(
																																					idd_ustanove_nd = :idd_ustanove_nd
																																					AND 
																																					idd_skole_ustanove_nd
																																					IN
																																					(
																																						SELECT
																																						id_skole_ustanove_nd
																																						FROM
																																						idk_nd_ustanove_skola
																																						WHERE
																																						(
																																							idd_ustanove_nd = :idd_ustanove_nd
																																							AND
																																							skola_idd = :skola_idd
																																						)
																																					)
																																					AND 
																																					idd_skole_smjer_ustanove_nd
																																					IN
																																					(
																																						SELECT
																																						id_skole_smjer_ustanove_nd
																																						FROM
																																						idk_nd_ustanove_skole_smjerovi
																																						WHERE
																																						(
																																							ss_idd = :ss_idd
																																							AND
																																							idd_skole_ustanove_nd
																																							IN
																																							(
																																								SELECT
																																								id_skole_ustanove_nd
																																								FROM
																																								idk_nd_ustanove_skola
																																								WHERE
																																								(
																																									idd_ustanove_nd = :idd_ustanove_nd
																																									AND
																																									skola_idd = :skola_idd
																																								)
																																							)
																																						)
																																					)
																																				)
																																			");
																							$tipovi_dokumenta_ustanove_k_ispis->execute(array(
																																':idd_ustanove_nd' => $ustanova_kandidata_ispis_otvoren,
																																':skola_idd' => $skola_nd_kandidata_ispis_otvoren_povezi,
