																										<?php
																											while($tipovi_dokumenta_ustanove_k_ispis_row = $tipovi_dokumenta_ustanove_k_ispis->fetch()){
																												$tip_id1 = $tipovi_dokumenta_ustanove_k_ispis_row['id_tip_dokumenta_ustanove_nd'];
																												$tip_naziv1 = $tipovi_dokumenta_ustanove_k_ispis_row['naziv_tip_dokumenta_ustanove_nd'];
																												$tip_povezanost1 = $tipovi_dokumenta_ustanove_k_ispis_row['povezanost_dokumenta_ustanove_nd'];
																												if($tip_povezanost1 == 1){
