																										</span>
																										<span class="fileinput-exists">
																											Promijeni
																										</span>
																										<input type="file" name="prilog_file_kan_bo[]" id="prilog_file_kan_bo" multiple="">
																									</span>
																									<i style="padding-top: 5px; padding-left: 10px; padding-right: 10px;" class="fa fa-question-circle fa-lg" data-toggle="tooltip" data-placement="right" title="Napomena: Dokument ne smije biti veći od 5MB! - Dozvoljeni formati: jpg, jpeg, pdf, doc, docx, xls, xlsx, txt, ppt, pptx, png, csv" aria-hidden="true">
																									</i>
																									<br>
																									<span style="padding-top: 5px; padding-left: 10px; padding-right: 10px; word-break: break-all;" id = "files-selected">
																									</span>
																									<br>
																									<span style="padding-top: 5px; padding-left: 10px; padding-right: 10px; word-break: break-all;" id = "files-name">
																									</span>
																									
																									<script>
																										$(function (){
																											$('#prilog_file_kan_bo').change(function (){
																												//Script za provjeru više dokumenata
																												if($('#prilog_file_kan_bo').val() !== ""){
																													var files = [];
																													var filesName = [];
																													files.push(this.files);
																													if(parseInt(this.files.length) < 11){
																														$('#files-selected').text(this.files.length + " file selected.");
																														iterateFiles(files);
																														function iterateFiles(filesArray)
																														{
																															var zastavicaPrilog = 0;
																															for(var i=0; i<filesArray.length; i++){
																																//console.log("I"+ i);
																																for(var j=0; j<filesArray[i].length; j++){
																																	//console.log("J"+ j);
																																	console.log(filesArray[i][j].name + " " + filesArray[i][j].size);
																																	filesName.push(filesArray[i][j].name);
																																	// alternatively: console.log(filesArray[i].item(j).name);
																																	var ext = filesArray[i][j].name.split('.').pop().toLowerCase();
																																	if($.inArray(ext, ['jpg', 'jpeg', 'pdf', 'doc', 'docx', 'xls', 'xlsx', 'txt', 'ppt', 'pptx', 'png']) == -1) {
																																		$('#prilog_alert_ext').removeClass('hidden');
																																		setTimeout(function(){
																																			$('#prilog_alert_ext').addClass('hidden');
																																		}, 5000);
																																		$('#prilog_file_kan_bo').val(null);
																																		zastavicaPrilog = 1;
																																		$('#files-selected').text("");
																																		console.log("Zaustavljen nastavak");
																																		break;
																																	}else{
																																		$('#prilog_alert_ext').addClass('hidden');
																																	}
																																	
																																	var f = filesArray[i][j];
																																	if (f.size > 5242880){
																																		$('#prilog_alert_size').removeClass('hidden');
																																		setTimeout(function(){
																																			$('#prilog_alert_size').addClass('hidden');
																																		}, 5000);
																																		$('#prilog_file_kan_bo').val(null);
																																		zastavicaPrilog = 1;
																																		$('#files-selected').text("");
																																		//console.log("Zaustavljen size");
																																		break;
																																	}else{
																																		$('#prilog_alert_size').addClass('hidden');
																																	}
																																}
																																if(zastavicaPrilog === 1){
																																	//console.log("Zaustavljena vanjska petlja");
																																	break;
																																}
																															}
																															if(zastavicaPrilog === 0){
																																$('#files-name').text("File-ovi: "+ filesName.join(" , ") + "");
																															}else{
																																$('#files-name').text("");
																																//console.log("Obrisan tekst fileova");
																															}
																														}
																													}else{
																														$('#prilog_file_kan_bo').val(null);
																														$('#files-name').text("");
																														$('#files-selected').text("");
																														$('#prilog_alert_len').removeClass('hidden');
																														setTimeout(function(){
																															$('#prilog_alert_len').addClass('hidden');
																														}, 5000);
																													}
																												}
																											})
																										});
																									</script>
																								</div>
																							</div>
																						</div>
